-- Sprint 5: health records and the non-feed operating expense ledger.
create table public.expense_categories(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,name text not null check(char_length(trim(name))between 2 and 120),system_code text, is_system boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),created_by uuid references public.profiles(id),updated_at timestamptz not null default now(),updated_by uuid references public.profiles(id));
create unique index expense_categories_farm_name_uidx on public.expense_categories(farm_id,lower(name));create unique index expense_categories_system_uidx on public.expense_categories(farm_id,system_code)where system_code is not null;create index expense_categories_farm_active_idx on public.expense_categories(farm_id,active);
create table public.expenses(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,expense_number text not null,expense_date date not null,category_id uuid not null references public.expense_categories(id)on delete restrict,description text not null check(char_length(trim(description))between 2 and 300),supplier_id uuid references public.suppliers(id)on delete restrict,payee_name text,amount numeric(14,2)not null check(amount>0),source_type text not null default'manual'check(source_type in('manual','health_record','daily_production')),source_id uuid,source_key text,status text not null default'active'check(status in('active','voided')),notes text,voided_at timestamptz,voided_by uuid references public.profiles(id),void_reason text,created_at timestamptz not null default now(),created_by uuid not null references public.profiles(id),updated_at timestamptz not null default now(),updated_by uuid references public.profiles(id),unique(farm_id,expense_number),check((source_type='manual'and source_key='manual')or(source_type<>'manual'and source_id is not null and source_key is not null)));
create unique index expenses_active_source_uidx on public.expenses(source_type,source_id,source_key)where source_type<>'manual'and status='active';create index expenses_farm_date_idx on public.expenses(farm_id,expense_date desc);create index expenses_category_date_idx on public.expenses(category_id,expense_date desc);create index expenses_source_idx on public.expenses(source_type,source_id,source_key);
create table public.expense_payments(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,expense_id uuid not null references public.expenses(id)on delete restrict,payment_date date not null,amount numeric(14,2)not null check(amount>0),payment_method text not null check(payment_method in('cash','momo','bank_transfer','other')),reference text,notes text,voided_at timestamptz,voided_by uuid references public.profiles(id),void_reason text,created_at timestamptz not null default now(),created_by uuid not null references public.profiles(id));create index expense_payments_expense_idx on public.expense_payments(expense_id);create index expense_payments_farm_date_idx on public.expense_payments(farm_id,payment_date desc);
create table public.health_records(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,flock_id uuid not null references public.flocks(id)on delete restrict,record_date date not null,health_type text not null check(health_type in('vaccine','antibiotic','vitamin','dewormer','treatment','veterinary_service','other')),product_name text not null check(char_length(trim(product_name))between 2 and 160),reason text,dose text,route text,duration text,quantity numeric(14,3)check(quantity>=0),quantity_unit text,veterinary_provider text,cost numeric(14,2)not null default 0 check(cost>=0),next_due_date date check(next_due_date is null or next_due_date>=record_date),notes text,status text not null default'active'check(status in('active','voided')),voided_at timestamptz,voided_by uuid references public.profiles(id),void_reason text,created_at timestamptz not null default now(),created_by uuid not null references public.profiles(id),updated_at timestamptz not null default now(),updated_by uuid references public.profiles(id));create index health_records_farm_date_idx on public.health_records(farm_id,record_date desc);create index health_records_flock_date_idx on public.health_records(flock_id,record_date desc);create index health_records_farm_due_idx on public.health_records(farm_id,next_due_date)where next_due_date is not null;
create trigger expense_categories_updated_at before update on public.expense_categories for each row execute function public.set_updated_at();create trigger expenses_updated_at before update on public.expenses for each row execute function public.set_updated_at();create trigger health_records_updated_at before update on public.health_records for each row execute function public.set_updated_at();

create function public.provision_expense_categories(target_farm uuid,target_user uuid default null)returns void language plpgsql security definer set search_path='' as $$begin insert into public.expense_categories(farm_id,name,system_code,is_system,created_by)select target_farm,x.name,x.code,true,target_user from(values('Medicine & Vaccines','medicine_vaccine'),('Transport','transport'),('Labour','labour'),('Utilities','utilities'),('Repairs & Maintenance','repairs_maintenance'),('Equipment','equipment'),('Packaging & Crates','packaging'),('Cleaning','cleaning'),('Veterinary','veterinary'),('Other','other'))x(name,code)on conflict do nothing;end;$$;
select public.provision_expense_categories(id,null)from public.farms;
create or replace function public.create_farm_with_admin(farm_name text)returns public.farms language plpgsql security definer set search_path='' as $$declare r public.farms;begin if auth.uid()is null then raise exception'Authentication required'using errcode='42501';end if;if char_length(trim(farm_name))not between 2 and 120 then raise exception'Invalid farm name'using errcode='22023';end if;insert into public.farms(name)values(trim(farm_name))returning*into r;insert into public.farm_settings(farm_id)values(r.id);insert into public.farm_members(farm_id,user_id,role)values(r.id,auth.uid(),'admin');perform public.provision_expense_categories(r.id,auth.uid());return r;end;$$;
create function public.expense_access_farm(required_roles text[])returns uuid language plpgsql security definer set search_path='' as $$declare f uuid;begin select farm_id into f from public.farm_members where user_id=auth.uid()and active and role=any(required_roles)order by created_at limit 1;if f is null then raise exception'Expense access denied'using errcode='42501';end if;return f;end;$$;
create function public.next_expense_number(f uuid,d date)returns text language plpgsql security definer set search_path='' as $$declare n bigint;begin perform pg_advisory_xact_lock(hashtextextended(f::text||d::text,0));select count(*)+1 into n from public.expenses where farm_id=f and expense_date=d;return'EXP-'||to_char(d,'YYYYMMDD')||'-'||lpad(n::text,4,'0');end;$$;
create function public.create_expense_category(name text)returns public.expense_categories language plpgsql security definer set search_path='' as $$declare f uuid;r public.expense_categories;begin f:=public.expense_access_farm(array['admin']);insert into public.expense_categories(farm_id,name,created_by)values(f,trim($1),auth.uid())returning*into r;return r;end;$$;
create function public.update_expense_category(target_category uuid,name text,active boolean)returns public.expense_categories language plpgsql security definer set search_path='' as $$declare r public.expense_categories;begin update public.expense_categories set name=trim($2),active=$3,updated_by=auth.uid()where id=$1 and public.is_farm_admin(farm_id)returning*into r;if r.id is null then raise exception'Category access denied'using errcode='42501';end if;return r;end;$$;
create function public.insert_generated_expense(f uuid,d date,cat_code text,descr text,amt numeric,stype text,sid uuid,skey text,creator uuid)returns public.expenses language plpgsql security definer set search_path='' as $$declare r public.expenses;c uuid;begin if amt<=0 then raise exception'Invalid expense amount'using errcode='23514';end if;select id into c from public.expense_categories where farm_id=f and system_code=cat_code;insert into public.expenses(farm_id,expense_number,expense_date,category_id,description,amount,source_type,source_id,source_key,created_by)values(f,public.next_expense_number(f,d),d,c,descr,amt,stype,sid,skey,creator)returning*into r;return r;end;$$;
create function public.create_expense(expense_date date,category_id uuid,description text,supplier_id uuid,payee_name text,amount numeric,initial_payment numeric default 0,payment_method text default'cash',reference text default null,notes text default null)returns public.expenses language plpgsql security definer set search_path='' as $$declare f uuid;r public.expenses;begin f:=public.expense_access_farm(array['admin','manager']);if $6<=0 or $7<0 or $7>$6 then raise exception'Invalid expense or payment amount'using errcode='23514';end if;if not exists(select 1 from public.expense_categories where id=$2 and farm_id=f and active)or($4 is not null and not exists(select 1 from public.suppliers where id=$4 and farm_id=f and active))then raise exception'Invalid category or supplier'using errcode='42501';end if;insert into public.expenses(farm_id,expense_number,expense_date,category_id,description,supplier_id,payee_name,amount,source_type,source_key,notes,created_by)values(f,public.next_expense_number(f,$1),$1,$2,trim($3),$4,nullif(trim($5),''),$6,'manual','manual',nullif(trim($10),''),auth.uid())returning*into r;if $7>0 then insert into public.expense_payments(farm_id,expense_id,payment_date,amount,payment_method,reference,created_by)values(f,r.id,$1,$7,$8,nullif(trim($9),''),auth.uid());end if;return r;end;$$;
create function public.record_expense_payment(target_expense uuid,payment_date date,amount numeric,payment_method text,reference text default null,notes text default null)returns public.expense_payments language plpgsql security definer set search_path='' as $$declare e public.expenses;paid numeric;r public.expense_payments;begin select*into e from public.expenses where id=$1 for update;if e.id is null or e.status<>'active'or not public.has_farm_role(e.farm_id,array['admin','manager'])then raise exception'Payment access denied'using errcode='42501';end if;select coalesce(sum(p.amount),0)into paid from public.expense_payments p where p.expense_id=e.id and p.voided_at is null;if $3<=0 or paid+$3>e.amount then raise exception'Payment exceeds remaining balance'using errcode='23514';end if;insert into public.expense_payments(farm_id,expense_id,payment_date,amount,payment_method,reference,notes,created_by)values(e.farm_id,e.id,$2,$3,$4,nullif(trim($5),''),nullif(trim($6),''),auth.uid())returning*into r;return r;end;$$;
create function public.update_expense(target_expense uuid,expense_date date,category_id uuid,description text,supplier_id uuid,payee_name text,amount numeric,notes text default null)returns public.expenses language plpgsql security definer set search_path='' as $$declare e public.expenses;r public.expenses;paid numeric;begin select*into e from public.expenses where id=$1 for update;if e.id is null or e.status<>'active'or e.source_type<>'manual'or not public.has_farm_role(e.farm_id,array['admin','manager'])then raise exception'Expense edit denied'using errcode='42501';end if;if not exists(select 1 from public.expense_categories where id=$3 and farm_id=e.farm_id)or($5 is not null and not exists(select 1 from public.suppliers where id=$5 and farm_id=e.farm_id))then raise exception'Invalid category or supplier'using errcode='42501';end if;select coalesce(sum(p.amount),0)into paid from public.expense_payments p where p.expense_id=e.id and p.voided_at is null;if $7<paid or $7<=0 then raise exception'Expense amount below active payments'using errcode='23514';end if;update public.expenses set expense_date=$2,category_id=$3,description=trim($4),supplier_id=$5,payee_name=nullif(trim($6),''),amount=$7,notes=nullif(trim($8),''),updated_by=auth.uid()where id=e.id returning*into r;return r;end;$$;
create function public.void_expense_payment(target_payment uuid,reason text)returns void language plpgsql security definer set search_path='' as $$declare f uuid;begin select farm_id into f from public.expense_payments where id=$1 for update;if f is null or not public.has_farm_role(f,array['admin'])or char_length(trim($2))<3 then raise exception'Payment void denied'using errcode='42501';end if;update public.expense_payments set voided_at=now(),voided_by=auth.uid(),void_reason=trim($2)where id=$1 and voided_at is null;end;$$;
create function public.void_expense(target_expense uuid,reason text)returns void language plpgsql security definer set search_path='' as $$declare e public.expenses;begin select*into e from public.expenses where id=$1 for update;if e.id is null or e.source_type<>'manual'or e.status<>'active'or not public.has_farm_role(e.farm_id,array['admin'])or char_length(trim($2))<3 then raise exception'Expense void denied'using errcode='42501';end if;if exists(select 1 from public.expense_payments where expense_id=e.id and voided_at is null)then raise exception'Active payments must be voided first'using errcode='23514';end if;update public.expenses set status='voided',voided_at=now(),voided_by=auth.uid(),void_reason=trim($2),updated_by=auth.uid()where id=e.id;end;$$;

create function public.create_health_record(flock_id uuid,record_date date,health_type text,product_name text,reason text default null,dose text default null,route text default null,duration text default null,quantity numeric default null,quantity_unit text default null,veterinary_provider text default null,cost numeric default 0,next_due_date date default null,notes text default null,initial_payment numeric default 0,payment_method text default'cash',reference text default null)returns public.health_records language plpgsql security definer set search_path='' as $$declare f uuid;ro text;r public.health_records;e public.expenses;begin select x.farm_id into f from public.flocks x where x.id=$1;select role into ro from public.farm_members where farm_id=f and user_id=auth.uid()and active;if ro is null then raise exception'Health access denied'using errcode='42501';end if;if ro='worker'and($12<>0 or $15<>0)then raise exception'Workers cannot enter health costs'using errcode='42501';end if;if $12<0 or coalesce($9,0)<0 or($13 is not null and $13<$2)or $15<0 or $15>$12 then raise exception'Invalid health values'using errcode='23514';end if;insert into public.health_records(farm_id,flock_id,record_date,health_type,product_name,reason,dose,route,duration,quantity,quantity_unit,veterinary_provider,cost,next_due_date,notes,created_by)values(f,$1,$2,$3,trim($4),nullif(trim($5),''),nullif(trim($6),''),nullif(trim($7),''),nullif(trim($8),''),$9,nullif(trim($10),''),nullif(trim($11),''),$12,$13,nullif(trim($14),''),auth.uid())returning*into r;if $12>0 then e:=public.insert_generated_expense(f,$2,case when $3='veterinary_service'then'veterinary'else'medicine_vaccine'end,'Health: '||trim($4),$12,'health_record',r.id,'health_cost',auth.uid());if $15>0 then insert into public.expense_payments(farm_id,expense_id,payment_date,amount,payment_method,reference,created_by)values(f,e.id,$2,$15,$16,nullif(trim($17),''),auth.uid());end if;end if;return r;end;$$;
create function public.update_health_record(target_health uuid,record_date date,health_type text,product_name text,reason text,dose text,route text,duration text,quantity numeric,quantity_unit text,veterinary_provider text,cost numeric,next_due_date date,notes text)returns public.health_records language plpgsql security definer set search_path='' as $$declare h public.health_records;r public.health_records;e public.expenses;paid numeric;ro text;begin select*into h from public.health_records where id=$1 for update;select role into ro from public.farm_members where farm_id=h.farm_id and user_id=auth.uid()and active;if h.id is null or ro is null or h.status<>'active'or(ro='worker'and(h.created_by<>auth.uid()or h.record_date<>((now()at time zone(select timezone from public.farms where id=h.farm_id))::date)or h.cost<>0 or $12<>0))then raise exception'Health edit denied'using errcode='42501';end if;if $12<0 or coalesce($9,0)<0 or($13 is not null and $13<$2)then raise exception'Invalid health values'using errcode='23514';end if;select*into e from public.expenses where source_type='health_record'and source_id=h.id and source_key='health_cost'and status='active'for update;select coalesce(sum(amount),0)into paid from public.expense_payments where expense_id=e.id and voided_at is null;if $12<paid then raise exception'Health cost below active payments'using errcode='23514';end if;if e.id is not null and $12=0 then update public.expenses set status='voided',voided_at=now(),voided_by=auth.uid(),void_reason='Health record cost removed',updated_by=auth.uid()where id=e.id;elsif e.id is not null then update public.expenses set expense_date=$2,category_id=(select id from public.expense_categories where farm_id=h.farm_id and system_code=case when $3='veterinary_service'then'veterinary'else'medicine_vaccine'end),description='Health: '||trim($4),amount=$12,updated_by=auth.uid()where id=e.id;elsif $12>0 then perform public.insert_generated_expense(h.farm_id,$2,case when $3='veterinary_service'then'veterinary'else'medicine_vaccine'end,'Health: '||trim($4),$12,'health_record',h.id,'health_cost',auth.uid());end if;update public.health_records set record_date=$2,health_type=$3,product_name=trim($4),reason=nullif(trim($5),''),dose=nullif(trim($6),''),route=nullif(trim($7),''),duration=nullif(trim($8),''),quantity=$9,quantity_unit=nullif(trim($10),''),veterinary_provider=nullif(trim($11),''),cost=$12,next_due_date=$13,notes=nullif(trim($14),''),updated_by=auth.uid()where id=h.id returning*into r;return r;end;$$;
create function public.void_health_record(target_health uuid,reason text)returns void language plpgsql security definer set search_path='' as $$declare h public.health_records;e public.expenses;begin select*into h from public.health_records where id=$1 for update;if h.id is null or h.status<>'active'or not public.has_farm_role(h.farm_id,array['admin'])or char_length(trim($2))<3 then raise exception'Health void denied'using errcode='42501';end if;select*into e from public.expenses where source_type='health_record'and source_id=h.id and status='active'for update;if exists(select 1 from public.expense_payments where expense_id=e.id and voided_at is null)then raise exception'Active payments must be voided first'using errcode='23514';end if;update public.health_records set status='voided',voided_at=now(),voided_by=auth.uid(),void_reason=trim($2),updated_by=auth.uid()where id=h.id;update public.expenses set status='voided',voided_at=now(),voided_by=auth.uid(),void_reason='Health record voided: '||trim($2),updated_by=auth.uid()where id=e.id;end;$$;

create function public.reconcile_production_expense(f uuid,pid uuid,d date,key text,amt numeric,creator uuid)returns void language plpgsql security definer set search_path='' as $$declare e public.expenses;paid numeric;begin select*into e from public.expenses where source_type='daily_production'and source_id=pid and source_key=key and status='active'for update;select coalesce(sum(amount),0)into paid from public.expense_payments where expense_id=e.id and voided_at is null;if amt<paid then raise exception'Production cost below active payments'using errcode='23514';end if;if e.id is not null and amt=0 then update public.expenses set status='voided',voided_at=now(),voided_by=creator,void_reason='Production cost removed',updated_by=creator where id=e.id;elsif e.id is not null then update public.expenses set amount=amt,expense_date=d,updated_by=creator where id=e.id;elsif amt>0 then perform public.insert_generated_expense(f,d,case when key='transport'then'transport'else'other'end,case when key='transport'then'Production transport cost'else'Production other cost'end,amt,'daily_production',pid,key,creator);end if;end;$$;

-- Replace Sprint 4 production functions, preserving all operational/feed behavior and adding expense reconciliation.
create or replace function public.create_daily_production(target_flock_id uuid,production_date date,eggs_collected integer,cracked_eggs integer,deaths integer,culls integer,feed_consumed_kg numeric,feed_type_id uuid,transport_cost numeric,other_cost numeric,notes text default null)returns public.daily_production_records language plpgsql security definer set search_path='' as $$declare f uuid;st text;role text;tz text;available integer;r public.daily_production_records;begin if auth.uid()is null then raise exception'Authentication required'using errcode='42501';end if;select x.farm_id,x.status,fa.timezone into f,st,tz from public.flocks x join public.farms fa on fa.id=x.farm_id where x.id=$1 for update of x;select fm.role into role from public.farm_members fm where fm.farm_id=f and fm.user_id=auth.uid()and fm.active;if role is null then raise exception'Production access denied'using errcode='42501';end if;if st<>'active'then raise exception'Closed flock'using errcode='22023';end if;if role='worker'and $2<>(now()at time zone tz)::date then raise exception'Workers may record current date only'using errcode='42501';end if;if $7>0 and not exists(select 1 from public.feed_types where id=$8 and farm_id=f and active)then raise exception'Valid feed type required'using errcode='23514';end if;available:=public.flock_balance_at($1,$2);if $5+$6>available then raise exception'Bird losses exceed available birds'using errcode='23514';end if;insert into public.daily_production_records(farm_id,flock_id,production_date,eggs_collected,cracked_eggs,deaths,culls,feed_consumed_kg,feed_type_id,transport_cost,other_cost,notes,created_by)values(f,$1,$2,$3,$4,$5,$6,$7,case when $7>0 then $8 end,$9,$10,nullif(trim($11),''),auth.uid())returning*into r;insert into public.egg_inventory_movements(farm_id,movement_date,movement_type,direction,quantity_eggs,source_type,source_id,created_by)values(f,$2,'production','IN',$3-$4,'daily_production',r.id,auth.uid());if $7>0 then insert into public.feed_inventory_movements(farm_id,flock_id,feed_type_id,movement_date,movement_type,direction,quantity_kg,source_type,source_id,created_by)values(f,$1,$8,$2,'consumption','OUT',$7,'daily_production',r.id,auth.uid());perform public.recalculate_feed_ledger(f,$8);end if;if $5>0 then insert into public.bird_movements(farm_id,flock_id,movement_date,movement_type,quantity,direction,source_type,source_id,created_by)values(f,$1,$2,'death',$5,'OUT','daily_production',r.id,auth.uid());end if;if $6>0 then insert into public.bird_movements(farm_id,flock_id,movement_date,movement_type,quantity,direction,source_type,source_id,created_by)values(f,$1,$2,'cull',$6,'OUT','daily_production',r.id,auth.uid());end if;perform public.reconcile_production_expense(f,r.id,$2,'transport',$9,auth.uid());perform public.reconcile_production_expense(f,r.id,$2,'other_cost',$10,auth.uid());perform public.assert_nonnegative_flock_history($1);return r;exception when unique_violation then raise exception'A production record already exists for this flock on this date'using errcode='23505';end;$$;
-- Wrap the existing Sprint 4 update logic by retaining its body with expense calls.
create or replace function public.update_daily_production(target_production_id uuid,eggs_collected integer,cracked_eggs integer,deaths integer,culls integer,feed_consumed_kg numeric,feed_type_id uuid,transport_cost numeric,other_cost numeric,notes text default null)returns public.daily_production_records language plpgsql security definer set search_path='' as $$declare e public.daily_production_records;r public.daily_production_records;old_type uuid;begin select*into e from public.daily_production_records where id=$1 for update;if e.id is null or not public.has_farm_role(e.farm_id,array['admin','manager'])then raise exception'Production edit access denied'using errcode='42501';end if;if $6>0 and not exists(select 1 from public.feed_types where id=$7 and farm_id=e.farm_id and active)then raise exception'Valid feed type required'using errcode='23514';end if;perform public.reconcile_production_expense(e.farm_id,e.id,e.production_date,'transport',$8,auth.uid());perform public.reconcile_production_expense(e.farm_id,e.id,e.production_date,'other_cost',$9,auth.uid());old_type:=e.feed_type_id;delete from public.bird_movements where source_type='daily_production'and source_id=e.id and movement_type in('death','cull');delete from public.feed_inventory_movements where source_type='daily_production'and source_id=e.id and movement_type='consumption';update public.daily_production_records set eggs_collected=$2,cracked_eggs=$3,deaths=$4,culls=$5,feed_consumed_kg=$6,feed_type_id=case when $6>0 then $7 end,transport_cost=$8,other_cost=$9,notes=nullif(trim($10),''),updated_by=auth.uid()where id=e.id returning*into r;update public.egg_inventory_movements set quantity_eggs=$2-$3 where source_type='daily_production'and source_id=e.id and movement_type='production';if $6>0 then insert into public.feed_inventory_movements(farm_id,flock_id,feed_type_id,movement_date,movement_type,direction,quantity_kg,source_type,source_id,created_by)values(e.farm_id,e.flock_id,$7,e.production_date,'consumption','OUT',$6,'daily_production',e.id,auth.uid());end if;if old_type is not null then perform public.recalculate_feed_ledger(e.farm_id,old_type);end if;if $7 is not null and $7 is distinct from old_type then perform public.recalculate_feed_ledger(e.farm_id,$7);end if;if $4>0 then insert into public.bird_movements(farm_id,flock_id,movement_date,movement_type,quantity,direction,source_type,source_id,created_by)values(e.farm_id,e.flock_id,e.production_date,'death',$4,'OUT','daily_production',e.id,auth.uid());end if;if $5>0 then insert into public.bird_movements(farm_id,flock_id,movement_date,movement_type,quantity,direction,source_type,source_id,created_by)values(e.farm_id,e.flock_id,e.production_date,'cull',$5,'OUT','daily_production',e.id,auth.uid());end if;perform public.assert_nonnegative_flock_history(e.flock_id);return r;end;$$;
create or replace function public.delete_daily_production(target_production_id uuid)returns void language plpgsql security definer set search_path='' as $$declare e public.daily_production_records;t uuid;begin select*into e from public.daily_production_records where id=$1 for update;if e.id is null or not public.has_farm_role(e.farm_id,array['admin'])then raise exception'Admin access required'using errcode='42501';end if;if exists(select 1 from public.expense_payments p join public.expenses x on x.id=p.expense_id where x.source_type='daily_production'and x.source_id=e.id and x.status='active'and p.voided_at is null)then raise exception'Active expense payments must be voided first'using errcode='23514';end if;update public.expenses set status='voided',voided_at=now(),voided_by=auth.uid(),void_reason='Production record deleted',updated_by=auth.uid()where source_type='daily_production'and source_id=e.id and status='active';t:=e.feed_type_id;delete from public.bird_movements where source_type='daily_production'and source_id=e.id;delete from public.egg_inventory_movements where source_type='daily_production'and source_id=e.id;delete from public.feed_inventory_movements where source_type='daily_production'and source_id=e.id;delete from public.daily_production_records where id=e.id;if t is not null then perform public.recalculate_feed_ledger(e.farm_id,t);end if;end;$$;
select public.reconcile_production_expense(farm_id,id,production_date,'transport',transport_cost,created_by)from public.daily_production_records where transport_cost>0;select public.reconcile_production_expense(farm_id,id,production_date,'other_cost',other_cost,created_by)from public.daily_production_records where other_cost>0;

create view public.v_expense_payables with(security_invoker=true)as select e.id expense_id,e.farm_id,e.expense_number,e.expense_date,e.category_id,c.name category_name,e.description,e.supplier_id,coalesce(s.name,e.payee_name)payee_name,e.amount,coalesce(sum(p.amount)filter(where p.voided_at is null),0)::numeric(14,2)total_paid,(e.amount-coalesce(sum(p.amount)filter(where p.voided_at is null),0))::numeric(14,2)outstanding_balance,case when coalesce(sum(p.amount)filter(where p.voided_at is null),0)=0 then'unpaid'when coalesce(sum(p.amount)filter(where p.voided_at is null),0)<e.amount then'partial'else'paid'end payment_status,e.source_type,e.status from public.expenses e join public.expense_categories c on c.id=e.category_id left join public.suppliers s on s.id=e.supplier_id left join public.expense_payments p on p.expense_id=e.id where e.status='active'group by e.id,c.name,s.name;
create view public.v_expense_summary with(security_invoker=true)as select e.farm_id,e.expense_date,date_trunc('month',e.expense_date)::date expense_month,e.category_id,c.name category_name,sum(e.amount)::numeric(14,2)total_amount from public.expenses e join public.expense_categories c on c.id=e.category_id where e.status='active'group by e.farm_id,e.expense_date,date_trunc('month',e.expense_date),e.category_id,c.name;
create view public.v_upcoming_health_actions with(security_invoker=true)as select h.*,f.flock_name from public.health_records h join public.flocks f on f.id=h.flock_id where h.status='active'and h.next_due_date is not null;
alter table public.expense_categories enable row level security;alter table public.expenses enable row level security;alter table public.expense_payments enable row level security;alter table public.health_records enable row level security;
create policy expense_categories_read on public.expense_categories for select to authenticated using(public.is_farm_member(farm_id));create policy expenses_read on public.expenses for select to authenticated using(public.has_farm_role(farm_id,array['admin','manager']));create policy expense_payments_read on public.expense_payments for select to authenticated using(public.has_farm_role(farm_id,array['admin','manager']));create policy health_read on public.health_records for select to authenticated using(public.is_farm_member(farm_id));
grant select on public.expense_categories,public.health_records,public.v_upcoming_health_actions to authenticated;grant select on public.expenses,public.expense_payments,public.v_expense_payables,public.v_expense_summary to authenticated;grant all on public.expense_categories,public.expenses,public.expense_payments,public.health_records to service_role;
revoke all on function public.provision_expense_categories(uuid,uuid),public.expense_access_farm(text[]),public.next_expense_number(uuid,date),public.insert_generated_expense(uuid,date,text,text,numeric,text,uuid,text,uuid),public.reconcile_production_expense(uuid,uuid,date,text,numeric,uuid)from public;
revoke all on function public.create_expense_category(text),public.update_expense_category(uuid,text,boolean),public.create_expense(date,uuid,text,uuid,text,numeric,numeric,text,text,text),public.record_expense_payment(uuid,date,numeric,text,text,text),public.update_expense(uuid,date,uuid,text,uuid,text,numeric,text),public.void_expense_payment(uuid,text),public.void_expense(uuid,text),public.create_health_record(uuid,date,text,text,text,text,text,text,numeric,text,text,numeric,date,text,numeric,text,text),public.update_health_record(uuid,date,text,text,text,text,text,text,numeric,text,text,numeric,date,text),public.void_health_record(uuid,text)from public;
grant execute on function public.create_expense_category(text),public.update_expense_category(uuid,text,boolean),public.create_expense(date,uuid,text,uuid,text,numeric,numeric,text,text,text),public.record_expense_payment(uuid,date,numeric,text,text,text),public.update_expense(uuid,date,uuid,text,uuid,text,numeric,text),public.void_expense_payment(uuid,text),public.void_expense(uuid,text),public.create_health_record(uuid,date,text,text,text,text,text,text,numeric,text,text,numeric,date,text,numeric,text,text),public.update_health_record(uuid,date,text,text,text,text,text,text,numeric,text,text,numeric,date,text),public.void_health_record(uuid,text)to authenticated;
